///////// 2. 초기화 영역 /////////
/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */
scwin.onpageload = function() {
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  URL 분리 처리
 */
scwin.getProvider = function() {
    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    const url = $c.frame.srcUrl;
    const arr = url.split("?")[1];
    return (arr.length >= 1 ? arr : undefined);
};

/**
 *  화면을 종료 처리
 */
scwin.closeWin = async function() {
    await $c.win.closePopup();
};
